  const rkValB = useMemo(() => parseF(b1, b2, b3, b4, unitMode, inputUnits['rk_b'] || 'mm'), [b1, b2, b3, b4, unitMode, inputUnits['rk_b']]);
  const rkValC = useMemo(() => parseF(c1, c2, c3, c4, unitMode, inputUnits['rk_c'] || 'mm'), [c1, c2, c3, c4, unitMode, inputUnits['rk_c']]);
  const rkValCD = useMemo(() => parseF(cd1, cd2, cd3, cd4, unitMode, inputUnits['rk_cd'] || 'mm'), [cd1, cd2, cd3, cd4, unitMode, inputUnits['rk_cd']]);
  const rkValCMW = useMemo(() => parseF(cmw1, cmw2, cmw3, cmw4, unitMode, inputUnits['rk_cmw'] || 'mm'), [cmw1, cmw2, cmw3, cmw4, unitMode, inputUnits['rk_cmw']]);
  
  const rkPitchVal = useMemo(() => parseFloat(c1) || 0, [c1]);
