                    <InputRow label="Layout Length (Optional)" v1={b1} v2={b2} v3={b3} v4={b4} setV1={setB1} setV2={setB2} setV3={setB3} setV4={setB4} mode={unitMode} theme={theme} onFocus={setActiveInput} {...getUnitProps('b')} infoId="rr-layout" activeInfo={activeInfo} toggleInfo={toggleInfo} customColor={accentColor} infoText="The total horizontal distance the roof covers along the wall, used to calculate material takeoffs and total rafter count."/>
