                    <div id="input-rr-ridge">
                      <InputRow label="Ridge Thick" v1={ridgeV1} v2={ridgeV2} v3={ridgeV3} v4={ridgeV4} setV1={setRidgeV1} setV2={setRidgeV2} setV3={setRidgeV3} setV4={setRidgeV4} mode={unitMode} theme={theme} hideFeet onFocus={setActiveInput} {...getUnitProps('ridge')} infoId="rr-ridge" activeInfo={activeInfo} toggleInfo={toggleInfo} customColor={secondaryColor} infoText="The physical thickness of the ridge board. Half of this thickness is automatically deducted from the run to find the true rafter length."/>
                    </div>
                    
                    {/* Full Width Seat Cut + Quick Wall-Plate Presets */}
