                <div id="input-st-width">
                  <InputRow label="Total Staircase Width (Defaults to 4')" v1={seatWidthV1} v2={seatWidthV2} v3={seatWidthV3} v4={seatWidthV4} setV1={setSeatWidthV1} setV2={setSeatWidthV2} setV3={setSeatWidthV3} setV4={setSeatWidthV4} mode={unitMode} theme={theme} onFocus={() => setActiveInput({ setV: setSeatWidthV1, setNum: setSeatWidthV3, setDen: setSeatWidthV4 })} {...getUnitProps('seat')} infoId="st-width" activeInfo={activeStairInfo} toggleInfo={toggleStairInfo} infoText="The total side-to-side width of the stairs. This is used to automatically calculate the number of stringers needed based on standard layout codes." />
                </div>

