                        <polygon points={isShort ? "26,90 30,86 30,106 26,110" : "26,30 30,26 30,106 26,110"} fill={theme === 'dark' ? '#444' : '#bbb'} stroke={theme === 'dark' ? '#333' : '#aaa'} strokeWidth="0.5" />

