                            {(['none', 'lattice', 'boards'] as const).map((mode) => (
                              <button key={mode} onClick={() => setC3(mode)}
                                className={`flex-1 py-2 rounded-lg text-[10px] font-bold uppercase tracking-widest active:scale-[0.97] transition-all duration-150 ${(c3 || 'none') === mode ? 'shadow-md border border-transparent' : 'bg-transparent text-[#888] hover:text-current'}`}
                                style={(c3 || 'none') === mode ? { backgroundColor: secondaryColor, color: '#fff' } : {}}
                              >
                                {mode === 'boards' ? 'Horiz. Boards' : mode}
                              </button>
                            ))}
