												const density = fiMaterialKey === 'custom'
													? (rawQty > 0 ? rawQty : 100)
													: (selectedMat ? selectedMat.lbsPerFt3 : (rawQty > 0 ? rawQty : 105.185));
												const wasteMultiplier = 1 + ((parseFloat(qty2) || 0) / 100);
												const orderCuFt = isI
													? (lenBase * widBase * depBase * wasteMultiplier)
													: (lenBase * widBase * depBase * wasteMultiplier * 35.3147);
												const orderCuM = isI
													? (orderCuFt * 0.0283168)
													: (lenBase * widBase * depBase * wasteMultiplier);
												const orderCuYds = orderCuFt / 27;
												const totalPounds = orderCuFt * density;
												const totalTons = totalPounds / 2000;
												const totalMetricTonnes = totalTons * 0.907185;
