                      const rawOrderVal = orderRow?.value || results.main || '';
                      const ydMatch = rawOrderVal.match(/([\d.]+)\s*yd³/i);
                      const mMatch = rawOrderVal.match(/([\d.]+)\s*m³/i);
                      const orderCuYds = parseFloat(ydMatch?.[1] || '0');
                      const orderCuM = parseFloat(mMatch?.[1] || '0');

                      const bags80Row = results.sub?.find((i: any) => i.label === '80lb Pre-Mix Bags')?.value || '0';
                      const bags60Row = results.sub?.find((i: any) => i.label === '60lb Pre-Mix Bags')?.value || '0';
                      const bags80lb = parseInt(bags80Row) || 0;
