// --- HELPER FUNCTIONS (NOW OUTSIDE THE APP) ---
const getStandardCap = (model: string): number => {
  return TRUCK_CAPACITIES[model as keyof typeof TRUCK_CAPACITIES]?.cap || 1500;
};

function parseInchesString(str: string) {
  let inches = '';
  let num = '';
  let den = '';

  const cleaned = (str || '').trim().replace(/"/g, '');
  if (!cleaned) {
    return { inches, num, den };
  }

  const parts = cleaned.split(/[\s-]+/).filter(Boolean);
  if (parts.length === 2) {
    inches = parts[0];
    if (parts[1].includes('/')) {
      const [n, d] = parts[1].split('/');
      num = n || '';
      den = d || '';
    }
  } else if (parts.length === 1) {
    if (parts[0].includes('/')) {
      const [n, d] = parts[0].split('/');
      num = n || '';
      den = d || '';
    } else {
      inches = parts[0];
    }
  }

  return { inches, num, den };
}

function parseImperialString(str: string) {
  let feet = '';
  let inches = '';
  let num = '';
  let den = '';

  const cleaned = (str || '').trim().replace(/"/g, '');
  if (!cleaned) {
    return { feet, inches, num, den };
  }

  let remaining = cleaned;
  if (cleaned.includes("'")) {
    const parts = cleaned.split("'");
    feet = parts[0].trim();
    remaining = parts.slice(1).join("'").trim();
  }

  if (remaining) {
    const parts = remaining.split(/[\s-]+/).filter(Boolean);
    if (parts.length === 2) {
      inches = parts[0];
      if (parts[1].includes('/')) {
        const [n, d] = parts[1].split('/');
        num = n || '';
        den = d || '';
      }
    } else if (parts.length === 1) {
      if (parts[0].includes('/')) {
        const [n, d] = parts[0].split('/');
        num = n || '';
        den = d || '';
      } else {
        inches = parts[0];
      }
    }
  }

  return { feet, inches, num, den };
}

function InputRow({ 
  label, icon, v1, v2, v3, v4, setV1, setV2, setV3, setV4, mode, theme, 
  hideFeet, hideInches, onFocus, unit, setUnit, hideM, hideMm, disabled, labelClassName, infoId, activeInfo, toggleInfo, infoText 
}: any) {
  const isI = mode === 'imp';
  const [isFocused, setIsFocused] = useState(false);
  const accentColor = typeof window !== 'undefined' ? (localStorage.getItem('appThemeColor') || '#06b6d4') : '#06b6d4';
  const inputClass = `rounded-lg p-3 w-full shadow-inner font-bold text-center focus:outline-none font-mono tracking-tight focus:border-[var(--accent-color)] focus:ring-1 focus:ring-[var(--accent-color)] transition-colors ${disabled ? 'opacity-30 cursor-not-allowed' : ''} ${theme !== 'light' ? 'bg-[#0B0F13] border border-gray-800 text-white' : 'bg-slate-100 text-slate-900 border border-slate-300'}`;
  
  // Strip spaces from the label to create a clean HTML name tag
  const safeName = label ? label.replace(/\s+/g, '') : 'input';

  const getInchesDisplayStr = () => {
    let inchPart = v2 || '';
    if (v3 && v4 && v4 !== '1' && v4 !== '0' && v3 !== '0') {
      if (inchPart && inchPart !== '0') {
        inchPart += ` ${v3}/${v4}`;
      } else {
        inchPart = `${v3}/${v4}`;
      }
    }
    return inchPart;
  };

  const currentInchesVal = getInchesDisplayStr();

  const handleInchesChange = (newVal: string) => {
    const { inches, num, den } = parseInchesString(newVal);
    setV2?.(inches);
    setV3?.(num);
    if (setV4) {
      setV4(den || '1');
    }
  };

  return (
    <div 
      onFocusCapture={() => setIsFocused(true)} 
      onBlurCapture={(e) => { if (!e.currentTarget.contains(e.relatedTarget as Node)) setIsFocused(false) }}
      className={`flex flex-col p-2.5 rounded-xl border transition-all duration-300 ${theme !== 'light' ? 'bg-[#111] border-[#222]' : 'bg-gray-100 border-[#ddd]'}`}
      style={isFocused ? { borderColor: 'var(--accent-color)', boxShadow: '0 0 0 2px var(--accent-color)' } : {}}
    >
      <div className="flex justify-between items-start mb-2 w-full">
        <div className="flex flex-col flex-1">
          <div className={`flex items-center gap-2 mb-1 ${infoId ? 'cursor-pointer uppercase font-extrabold text-xs tracking-widest' : ''} ${labelClassName || ''}`} style={infoId ? { color: accentColor } : {}} onClick={() => { if(toggleInfo && infoId) toggleInfo(infoId); }}>
            <span className={`flex items-center gap-1.5 text-xs font-extrabold uppercase tracking-widest`} style={!infoId ? { color: accentColor } : {}}>
              {icon ? icon : (typeof label === 'string' && !label.includes('Wall Run') && (label.includes('Side') || label.includes('Rise') || label.includes('Run') || label.includes('Diagonal'))) ? <Triangle size={14} /> : <Ruler size={14} />}
              {label}
            </span>
            {infoId && <Info size={14} />}
          </div>
          {infoId && activeInfo === infoId && (
            <div className="text-gray-400 text-xs italic bg-gray-900/50 p-2 rounded border-l-2 border-[var(--accent-color)] mb-4 w-full text-left font-normal tracking-normal capitalize-none">
              {infoText}
            </div>
          )}
        </div>
        {!isI && setUnit && (
          <div className={`flex border rounded-md p-0.5 scale-75 origin-right ${theme !== 'light' ? 'bg-[#000] border-[#333]' : 'bg-white border-[#ccc]'}`}>
            {(['m', 'cm', 'mm'] as const).map(u => {
              if (u === 'm' && hideM) return null;
              if (u === 'mm' && hideMm) return null;
              return (
                <button key={u} onClick={() => setUnit(u)}
                  className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase  ${unit === u ? 'bg-accent text-black shadow-[0_0_5px_rgba(0,210,255,0.3)]' : 'text-[#555] hover:text-[#888]'} active:scale-[0.97] active:shadow-inner active:brightness-90 transition-all duration-150`}
                >
                  {u}
                </button>
              );
            })}
          </div>
        )}
      </div>
      {isI ? (
        <DimensionInput
          label=""
          mode={hideFeet ? 'inches-only' : 'feet-inches'}
          feetValue={v1 || ''}
          onFeetChange={setV1}
          inchesValue={currentInchesVal}
          onInchesChange={handleInchesChange}
          theme={theme}
        />
      ) : (
        <div className="grid grid-cols-1 gap-1.5">
          <input inputMode="decimal" type="number" name={`${safeName}MET`} value={v1} onFocus={(e) => { e.target.select(); onFocus?.({ setV: setV1 }); }} onChange={(e) => setV1(e.target.value)} disabled={disabled} placeholder={unit || 'mm'} className={inputClass} />
        </div>
      )}
    </div>
  );
}

function InputWrap({ value, onChange, placeholder, theme, disabled }: any) {
  const [isFocused, setIsFocused] = useState(false);
  return (
    <div 
      onFocusCapture={() => setIsFocused(true)} 
      onBlurCapture={(e) => { if (!e.currentTarget.contains(e.relatedTarget as Node)) setIsFocused(false) }}
      className={`border rounded-lg p-3 flex items-center transition-all duration-300 ${theme !== 'light' ? 'bg-[#111] border-[#222]' : 'bg-white border-[#ddd]'} ${disabled ? 'opacity-50' : ''}`}
      style={isFocused ? { borderColor: 'var(--accent-color)', boxShadow: '0 0 0 2px var(--accent-color)' } : {}}
    >
      <input inputMode="decimal" type="number" value={value} onFocus={(e) => e.target.select()} onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
        className="bg-transparent border-none text-base w-full outline-none text-center font-mono tracking-tight"
      />
    </div>
  );
}